import { createSlice } from "@reduxjs/toolkit";
import mongoose from "mongoose";


interface IUser {
  _id?: mongoose.Types.ObjectId;

  name: string;
  email: string;
  password?: string;
  image?: string;

  role: "user" | "vendor" | "admin";
  phone?: string;

  /* -------------------- VENDOR FIELDS -------------------- */
  shopName?: string;
  businessAddress?: string;
  gstNumber?: string;

  isApproved?: boolean;

  verificationStatus?: "pending" | "approved" | "rejected";
  requestedAt?: Date;
  approvedAt?: Date;
  rejectedReason?: string;

  /* -------------------- PRODUCT & ORDER REFERENCES -------------------- */
  vendorProducts?: mongoose.Types.ObjectId[]; // ✅ Products created by vendor
  orders?: mongoose.Types.ObjectId[];         // ✅ Orders placed by user

  /* -------------------- CART DATA -------------------- */
  cart?: {
    product: mongoose.Types.ObjectId;
    quantity: number;
  }[];

  createdAt?: Date;
  updatedAt?: Date;
}


interface IProduct {
  _id?: mongoose.Types.ObjectId;

  title: string;
  description: string;
  price: number;

  stock: number;                 // ✅ Total quantity
  isStockAvailable?: boolean;    // ✅ True = In stock | False = Out of stock

  image1: string;
   image2: string;
    image3: string;
     image4: string;
  category: string;

  // ✅ Vendor who created this product
  vendor: mongoose.Types.ObjectId;

  // ✅ ADMIN VERIFICATION FOR PRODUCT
  verificationStatus?: "pending" | "approved" | "rejected";
  rejectedReason?: string;
  approvedAt?: Date;

  // ✅ Admin can enable/disable product anytime
  isActive?: boolean;      // ✅ true = visible | false = hidden

  createdAt?: Date;
  updatedAt?: Date;
}
interface IuserSlice{
    allVendorData: IUser[],
    allProductsData: IProduct[]
}

const initialState:IuserSlice = {
    allVendorData:[],
    allProductsData:[]
}
const vendorSlice = createSlice({
    name:"vendor",
    initialState,
    reducers:{
    setAllVendorData:(state,action)=>{
        state.allVendorData = action.payload
    },
    setAllProductsData:(state,action)=>{
      state.allProductsData = action.payload
    }

    }

    
})

export const {setAllVendorData} = vendorSlice.actions
export const {setAllProductsData} = vendorSlice.actions
export default vendorSlice.reducer